import { useState, useEffect } from 'react';
import axios from 'axios';

const Category = () => {
    const [categories, setCategories] = useState([]);

    useEffect(() => {
    fetchCategories();
    }, []);

    const fetchCategories = async () => {
        try {   
            const response = await axios.get('http://localhost:5000/api/users/allcategories');
            setCategories(response.data);
        } catch (error) {
            console.error("Error fetching categories:", error); 
        }
    };
 const handleAddCategory = async (e) => {
        e.preventDefault();     
        const name = e.target.name.value;
        try {   
            const response = await axios.post('http://localhost:5000/api/users/addcategory', { name });
            console.log("Category added:", response.data);
            fetchCategories(); // Refresh the list after adding
            e.target.reset(); // Reset the form
        }   catch (error) { 
            console.error("Error adding category:", error);
        }       

    };
     return (
    <div style={{ padding: "30px" }}>
      <h1>Categories</h1>

     
      <form onSubmit={handleAddCategory} style={{ marginBottom: "20px" }}>
        <input
          type="text"
          name="name"
          placeholder="Enter Category Name"
          required
          style={{ padding: "10px", marginRight: "10px", width: "250px" }}
        />
           <button style={{backgroundColor: 'black',
        color: 'white',           
          border: '1px solid #ddd',           
          borderRadius: '8px',              
          padding: '6px 16px',                
          fontSize: '14px',                   
          fontWeight: 500,                 
          minWidth: '115px',            
          height: '45px',                  
          alignItems: 'center',              
          gap: '3px',
          cursor: 'pointer',}} onClick={() => setShowForm(true)}>
          Add Product
        </button>
      </form>

            {/*  Modal Form */}
      {showForm && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h2>Add New Product</h2>
            <form onSubmit={handleAddProduct} encType="multipart/form-data">
              <input
                type="text"
                name="name"
                placeholder="Name"
                value={formData.name}
                onChange={handleChange}
                required
              />
              <input
                type="text"
                name="category"
                placeholder="Category"
                value={formData.category}
                onChange={handleChange}
                required
              />
              <input
                type="number"
                name="price"
                placeholder="Price"
                value={formData.price}
                onChange={handleChange}
                required
              />
              <input
                type="text"
                name="brand"
                placeholder="Brand"
                value={formData.brand}
                onChange={handleChange}
                required
              />
              <input
                type="file"
                name="image"
                accept="image/*"
                onChange={handleFileChange}
                required
              />
              <div className="form-buttons">
                <button type="submit" className="square-btn view">
                  Submit
                </button>
                <button
                  type="button"
                  className="square-btn delete"
                  onClick={() => setShowForm(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div>
        <h3>Available Categories:</h3>
        <ul>
          {categories.map((cat) => (
            <li key={cat._id}>{cat.name}</li>
          ))}
        </ul>
      </div>
    </div>
  );
};
export default Category;
